use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;
use crate::aap::caps::types::{AgentResponse, LlmError};

struct Node;

/// Upper bound on tool-orchestration rounds, so a model that keeps asking for
/// tools instead of answering cannot spin forever.
const MAX_ROUNDS: u32 = 8;

/// The one tool in this node's scope (`LLMClient<[lookup]>`), backed by the
/// read-only `DBHandle<'knowledge-base', read>` import. Any other tool name the
/// model asks for is out of scope and is not invoked.
const LOOKUP_TOOL: &str = "lookup";

const SYSTEM: &str =
    "You are a customer-support agent. Answer the user's question using only the \
     provided knowledge and the knowledge-base lookup tool. If you need more \
     facts, ask for the `lookup` tool; otherwise answer directly.";

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut prompt = String::new();
    prompt.push_str("Intent: ");
    prompt.push_str(match ctx.intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    });
    prompt.push('\n');

    if !ctx.knowledge.is_empty() {
        prompt.push_str("Knowledge:\n");
        for k in &ctx.knowledge {
            prompt.push_str("- ");
            prompt.push_str(k);
            prompt.push('\n');
        }
    }

    prompt.push_str("Question: ");
    prompt.push_str(&ctx.question);
    prompt
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512`, enforced defensively on the way in.
        // `len` is the Python-side character count of the string field.
        if ctx.question.chars().count() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds the 512-character limit".to_string(),
            });
        }

        let mut prompt = build_prompt(&ctx);

        for round in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    if round + 1 >= MAX_ROUNDS {
                        return ResponseResult::Error(LlmError {
                            message: "tool-orchestration did not converge".to_string(),
                        });
                    }

                    let results = if req.tool == LOOKUP_TOOL {
                        kb_read::lookup(&req.query)
                    } else {
                        // Out-of-scope tool request: report it back as having no
                        // result rather than fabricating authority we lack.
                        Vec::new()
                    };

                    prompt.push_str("\nTool `");
                    prompt.push_str(&req.tool);
                    prompt.push_str("` results:\n");
                    if results.is_empty() {
                        prompt.push_str("(no results)\n");
                    } else {
                        for r in &results {
                            prompt.push_str("- ");
                            prompt.push_str(r);
                            prompt.push('\n');
                        }
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration did not converge".to_string(),
        })
    }
}

export!(Node);
